import React, { useState } from "react";

export type TradeSide = "buy" | "sell";

export interface TradingPanelProps {
  /** Optional callback invoked after a trade request succeeds. */
  onTrade?: (side: TradeSide, ticker: string, quantity: number) => void;
}

/**
 * Trading form: ticker + quantity inputs with Buy and Sell buttons.
 * Submits to POST /api/portfolio/trade and reports the outcome in the panel.
 */
export default function TradingPanel({ onTrade }: TradingPanelProps): React.ReactElement {
  const [ticker, setTicker] = useState("");
  const [quantity, setQuantity] = useState("1");
  const [status, setStatus] = useState<string>("");
  const [busy, setBusy] = useState(false);

  async function submit(side: TradeSide) {
    const qty = Number(quantity);
    const sym = ticker.trim().toUpperCase();
    if (!sym) {
      setStatus("Enter a ticker");
      return;
    }
    if (!Number.isFinite(qty) || qty <= 0) {
      setStatus("Quantity must be positive");
      return;
    }
    setBusy(true);
    setStatus("");
    try {
      const res = await fetch("/api/portfolio/trade", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ticker: sym, quantity: qty, side }),
      });
      if (!res.ok) {
        setStatus(`Trade failed (${res.status})`);
      } else {
        setStatus(`${side.toUpperCase()} ${qty} ${sym} filled`);
        onTrade?.(side, sym, qty);
      }
    } catch {
      setStatus("Network error");
    } finally {
      setBusy(false);
    }
  }

  return (
    <form
      data-testid="trading-panel"
      className="trading-panel"
      onSubmit={(e) => e.preventDefault()}
    >
      <label>
        Ticker
        <input
          data-testid="trade-ticker"
          value={ticker}
          onChange={(e) => setTicker(e.target.value)}
        />
      </label>
      <label>
        Quantity
        <input
          data-testid="trade-quantity"
          type="number"
          min="1"
          value={quantity}
          onChange={(e) => setQuantity(e.target.value)}
        />
      </label>
      <button
        type="button"
        data-testid="trade-buy"
        disabled={busy}
        onClick={() => submit("buy")}
      >
        Buy
      </button>
      <button
        type="button"
        data-testid="trade-sell"
        disabled={busy}
        onClick={() => submit("sell")}
      >
        Sell
      </button>
      <p data-testid="trade-status" role="status">{status}</p>
    </form>
  );
}

